// === Tab: mySketch ===
let s1;
let s2;
let angle = 0;

function setup() {
	createCanvas(windowWidth, 768, WEBGL);
  // create and initialize the shader
  s1 = createShader(vs, fs);
	s2 = createShader(vs, fs2);
  noStroke();

}

function draw() {
  s1.setUniform ('u_resolution', float(width), float(height));
	s1.setUniform ('u_time', millis()/3200.0);
	shader(s1);
  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

function mousePressed(){
	save('myimage.jpg');
}

// === Tab: vertexShader ===
let vs = `
attribute vec3 aPosition;
varying vec2 vPos;
void main() {
  vPos = vec2(aPosition.x,aPosition.y);
	gl_Position = vec4(aPosition,1.0);
}
`;

// === Tab: fragmentShader ===
let fs = `
precision mediump float;
#define PI 3.14159265359
#define TWO_PI 6.28318530718

uniform vec2 u_resolution;
uniform float u_time;
varying vec2 vPos;

//  Function from Iñigo Quiles
//  https://www.shadertoy.com/view/MsS3Wc
vec3 hsb2rgb( in vec3 c ){
    vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                             6.0)-3.0)-1.0,
                     0.0,
                     1.0 );
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void main() {
    vec2 st = ((vPos+1.0) / 2.0); // !!!!!!!!!!!!! this is what makes shaders work in p5
    vec3 color = vec3(0.0); //inital color

    // Use polar coordinates instead of cartesian
    vec2 toCenter = vec2(0.5)-st; // location of the center
    float angle = atan(toCenter.y,toCenter.x); 
    float radius = length(toCenter)*2.0; // distance from vector to center (used to determine saturation)

    // Map the angle (-PI to PI) to the Hue (from 0 to 1)
    // and the Saturation to the radius
    color = hsb2rgb(vec3((angle/TWO_PI)+u_time,radius,1.0)); // hue (angle), saturation (radius), brightness (full)

    gl_FragColor = vec4(color,1.0);
}
`;

// === Tab: fs2 ===
let fs2 = `
 precision mediump float;
 uniform vec2 u_resolution;
 uniform float u_time;

 vec3 colorA = vec3(0.949,0.494,0.623);
 vec3 colorB = vec3(25.0/255.0,162.0/255.0,209.0/255.0);

 void main() {
		float pct = abs(sin(u_time));
		vec3 color = mix(colorB, colorA, pct);
    gl_FragColor = vec4(color,1.0);
}
`;

